// Requêtes de recherche par niche ciblée CI
const queries = [
  // Secrétariat & Assistanat direction
  { query: '"secrétaire de direction" OR "assistante de direction" "Abidjan" email contact site:linkedin.com', niche: 'assistant_direction_documentaire', label: 'Secrétariat Direction CI' },
  { query: '"secrétariat" "organisation internationale" "Côte d\'Ivoire" OR "Abidjan" directeur email', niche: 'assistant_direction_documentaire', label: 'Orgs Internationales CI' },
  // Banque & Finance
  { query: '"directeur" banque microfinance "Côte d\'Ivoire" OR "Abidjan" email contact 2025', niche: 'banque_kyc_reporting', label: 'Banques & Microfinance CI' },
  // PME & Entreprises privées
  { query: 'PME entreprise "Abidjan" "directeur général" email site:abidjan.net OR site:fratmat.info 2025', niche: 'workflow_administratif', label: 'PME Abidjan' },
  // Santé
  { query: '"directeur" clinique hôpital "Côte d\'Ivoire" OR "Abidjan" email contact', niche: 'telemedecine_triage_orientation', label: 'Santé CI' },
  // Recrutement & RH
  { query: '"DRH" OR "directeur ressources humaines" "Abidjan" OR "Côte d\'Ivoire" email 2025', niche: 'recrutement_onboarding_augmente', label: 'RH & Recrutement CI' },
  // Organisations internationales
  { query: '"représentant pays" OR "country director" "Côte d\'Ivoire" OR "Abidjan" ONG organisation email 2025', niche: 'assistant_direction_documentaire', label: 'ONG & Orgs Intl CI' },
  // Marketing & Communication
  { query: '"directeur marketing" OR "directeur communication" "Abidjan" entreprise email contact 2025', niche: 'machine_contenu_marketing', label: 'Marketing CI' }
];

return queries.map(q => ({ json: q }));

const serperResult = $input.all()[0].json;
const queryCtx = $('Une Requête à la Fois').first().json;

// Combine organic results + knowledge graph
const organic = serperResult.organic || [];
const snippet_texts = organic.map(r => `Titre: ${r.title}\nURL: ${r.link}\nExtrait: ${r.snippet || ''}`).join('\n\n');

if (!snippet_texts.trim()) return [];

return [{
  json: {
    niche: queryCtx.niche,
    label: queryCtx.label,
    raw_results: snippet_texts.substring(0, 4000)
  }
}];

