parameters.jsCode:
const gptRaw = $input.all()[0].json;
const ctx = $('Préparer Contexte GPT').first().json;

let prospects = [];
try {
  const content = gptRaw.choices?.[0]?.message?.content || '';
  const parsed = JSON.parse(content);
  prospects = parsed.prospects || [];
} catch(e) {
  return [];
}

// Attach niche to each prospect
return prospects
  .filter(p => p.organization_name && p.organization_name.length > 2)
  .map(p => ({
    json: {
      ...p,
      niche_status: ctx.niche,
      source_label: 'serper_daily_enrichment',
      source_backend: 'serper',
      commercial_priority_default: 'tier2',
      research_scope: 'public_web_only',
      country: p.country || 'Côte d\'Ivoire'
    }
  }));

const dupResult = $input.all()[0].json;
const prospect = $('Un Prospect à la Fois').first().json;

const existing = Array.isArray(dupResult) ? dupResult : [];
const isNew = existing.length === 0;

return [{ json: { ...prospect, _is_new: isNew } }];

const p = $json;

// Generate a clean prospect_id from org name
const slug = (p.organization_name || 'unknown')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .substring(0, 40);

const prospect_id = `serper-${slug}-${Date.now().toString(36)}`;

return [{
  json: {
    prospect_id,
    organization_name: p.organization_name || '',
    decision_maker_name: p.decision_maker_name || 'Directeur Général',
    target_email: p.target_email || '',
    website: p.website || '',
    sector_guess: p.sector_guess || '',
    country: p.country || "Côte d'Ivoire",
    organization_type: p.organization_type || 'Entreprise privée',
    niche_status: p.niche_status || 'workflow_administratif',
    status: 'ready',
    source_label: 'serper_daily_enrichment',
    source_backend: 'serper',
    commercial_priority_default: 'tier2',
    research_scope: 'public_web_only',
    created_at: new Date().toISOString()
  }
}];

// Count inserted vs skipped
const allItems = $input.all();
const inserted = allItems.filter(i => i.json.prospect_id).length;

return [{ json: { inserted_count: inserted, run_date: new Date().toISOString().slice(0,10) } }];

